import itertools

def is_golomb(marks):
    diffs = set()
    for i in range(len(marks)):
        for j in range(i + 1, len(marks)):
            d = marks[j] - marks[i]
            if d in diffs:
                return False
            diffs.add(d)
    return True

def find_golomb(n, fixed_marks):
    # fixed_marks is a dictionary {index: value}
    # We need to find marks x_0, ..., x_{n-1}
    # x_0 = 0
    # x_1 = 2

    # Let's try a backtracking search
    marks = [0] * n
    for idx, val in fixed_marks.items():
        marks[idx] = val

    def backtrack(idx, current_marks):
        if idx == n:
            return current_marks

        # Determine range for current_marks[idx]
        start = current_marks[idx-1] + 1
        # We don't have an upper bound, but let's try a reasonable one
        for val in range(start, 100):
            new_marks = current_marks[:]
            new_marks[idx] = val

            # Check if new_marks is valid so far
            # Only need to check differences involving new_marks[idx]
            valid = True
            diffs = set()
            for i in range(idx + 1):
                for j in range(i + 1, idx + 1):
                    d = new_marks[j] - new_marks[i]
                    if d in diffs:
                        valid = False
                        break
                    diffs.add(d)

            if valid:
                res = backtrack(idx + 1, new_marks)
                if res:
                    return res
        return None

    return backtrack(2, marks)

# x_0=0, x_1=2
print(find_golomb(7, {0: 0, 1: 2}))
